using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Informs TDLib that a story is opened and is being viewed by the user
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> OpenStoryAsync(long storyPosterChatId = default, int storyId = default)
    {

           using var activity =  StartCallActivity("OpenStoryAsync", typeof(OpenStory).FullName ?? "OpenStoryAsync");

           try
           {
             return client.OpenStoryAsync(storyPosterChatId, storyId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
